# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: Building blocks shared by the three look pages: highlighted code
#          lines, table renderers (HTML and box-drawing), and the look switcher.
# ---------------------------------------------------------------------------
from __future__ import annotations

import reflex as rx

LOOKS = ["tui", "hybrid", "zed", "widgets", "thread", "split", "shelf", "canvas"]


def code_line(tokens: list[tuple[str, str]], number: int | None = None, cursor: bool = False) -> rx.Component:
    """One line of fake-highlighted code, optionally with a gutter number."""
    parts: list[rx.Component] = []
    if number is not None:
        parts.append(rx.el.span(str(number), class_name="ln"))
    parts.extend(rx.el.span(text, class_name=f"t-{cls}" if cls else "") for text, cls in tokens)
    if cursor:
        parts.append(rx.el.span(" ", class_name="cursor"))
    return rx.el.div(*parts, class_name="line")


def code_block(lines: list[list[tuple[str, str]]], start: int | None = None, cursor: bool = False) -> rx.Component:
    return rx.el.div(
        *[
            code_line(tokens, None if start is None else start + i, cursor and i == len(lines) - 1)
            for i, tokens in enumerate(lines)
        ],
        class_name="code",
    )


def html_table(columns: list[tuple[str, str]], rows: list[tuple[str, ...]]) -> rx.Component:
    """Dataframe output as a real HTML table (column name over dtype)."""
    numeric = [dtype != "str" for _, dtype in columns]
    return rx.el.table(
        rx.el.thead(
            rx.el.tr(
                *[
                    rx.el.th(name, rx.el.span(dtype, class_name="dtype"), class_name="num" if numeric[i] else "")
                    for i, (name, dtype) in enumerate(columns)
                ]
            )
        ),
        rx.el.tbody(
            *[
                rx.el.tr(*[rx.el.td(value, class_name="num" if numeric[i] else "") for i, value in enumerate(row)])
                for row in rows
            ]
        ),
        class_name="df",
    )


def box_table(columns: list[tuple[str, str]], rows: list[tuple[str, ...]]) -> str:
    """Dataframe output as polars-style box-drawing text, for the TUI look."""
    widths = [max(len(name), len(dtype), *(len(row[i]) for row in rows)) for i, (name, dtype) in enumerate(columns)]

    def row_text(values: list[str], sep: str = "┆") -> str:
        cells = [f" {value:<{widths[i]}} " for i, value in enumerate(values)]
        return "│" + sep.join(cells) + "│"

    def rule(left: str, mid: str, right: str, fill: str = "─") -> str:
        return left + mid.join(fill * (w + 2) for w in widths) + right

    return "\n".join(
        [
            f"shape: ({len(rows)}, {len(columns)})",
            rule("┌", "┬", "┐"),
            row_text([name for name, _ in columns]),
            row_text([dtype for _, dtype in columns]),
            rule("╞", "╪", "╡", "═"),
            *[row_text(list(row)) for row in rows],
            rule("└", "┴", "┘"),
        ]
    )


def switcher(current: str) -> rx.Component:
    """Fixed corner links for flipping between the looks."""
    return rx.el.div(
        *[rx.el.a(look, href=f"/{look}", class_name="is-current" if look == current else "") for look in LOOKS],
        class_name="switcher",
    )
